keyframes:
@keyframes cWave { 
  0%, 9%, 100% { transform: translateY(0px); }
  4% { transform: translateY(-10px); }
}
@keyframes cSweep { 
  0% { transform: translateX(-160%) skewX(-16deg); }
  60%, 100% { transform: translateX(360%) skewX(-16deg); }
}
@keyframes cScan { 
  0%, 100% { transform: translateY(0px); opacity: 0; }
  12% { opacity: 0.85; }
  50% { transform: translateY(560px); opacity: 0.85; }
  70% { opacity: 0; }
}
@keyframes cDraw { 
  0%, 100% { stroke-dashoffset: 0; }
  46% { stroke-dashoffset: var(--len, 1400); }
}
@keyframes cReel { 
  0%, 100% { transform: translateY(var(--end, -80%)); }
  42% { transform: translateY(0px); }
}
@keyframes cNeedle { 
  0%, 100% { transform: rotate(var(--rest, 42deg)); }
  50% { transform: rotate(-42deg); }
}
@keyframes cBar { 
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(var(--low, 0.2)); }
}
@keyframes cGrowX { 
  0%, 100% { transform: scaleX(1); }
  50% { transform: scaleX(var(--low, 0.18)); }
}
@keyframes cPop { 
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.12); }
}
@keyframes cFloat { 
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-16px); }
}
@keyframes cWipe { 
  0%, 100% { clip-path: inset(0px); }
  50% { clip-path: inset(0px 100% 0px 0px); }
}
@keyframes cWipeU { 
  0%, 100% { clip-path: inset(0px); }
  50% { clip-path: inset(100% 0px 0px); }
}
@keyframes cType { 
  0%, 22%, 100% { clip-path: inset(0px); }
  46% { clip-path: inset(0px 100% 0px 0px); }
}
@keyframes cCaret { 
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@keyframes cKen { 
  0% { transform: scale(1.04); }
  100% { transform: scale(1.13); }
}
@keyframes cFlick { 
  0%, 100% { opacity: 1; }
  48% { opacity: 0.5; }
}
@keyframes cSpin { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes cMarq { 
  0% { transform: translateX(0px); }
  100% { transform: translateX(-50%); }
}
@keyframes cFlipA { 
  0%, 38%, 100% { opacity: 1; }
  50%, 88% { opacity: 0; }
}
@keyframes cFlipB { 
  0%, 38%, 100% { opacity: 0; }
  50%, 88% { opacity: 1; }
}
@keyframes cRing { 
  0%, 100% { stroke-dashoffset: 0; }
  48% { stroke-dashoffset: var(--clen, 1583); }
}
@keyframes cKnob { 
  0%, 100% { transform: translateX(var(--kx, 74px)); }
  50% { transform: translateX(0px); }
}
@keyframes cRipple { 
  0% { transform: scale(0.4); opacity: 0.5; }
  70%, 100% { transform: scale(3.2); opacity: 0; }
}
@keyframes cStamp { 
  0%, 100% { transform: scale(1) rotate(-9deg); opacity: 1; }
  44% { transform: scale(1.7) rotate(-9deg); opacity: 0; }
  56% { opacity: 0; }
}
@keyframes cRise { 
  0%, 12%, 100% { transform: translateY(0px); opacity: 1; }
  50% { transform: translateY(40px); opacity: 0; }
}
